			return true
		case groups[i].Freshness.Detail != "":
			groups[i].Freshness.Detail = ""
			return true
		case groups[i].Freshness.ContractDetail != "":
			groups[i].Freshness.ContractDetail = ""
			return true
		}
	}
	return false
}

