	go func() {
		stats, err := runMemoryAbstractLane(ctx, t.TempDir(), brainDir, now, "abstract-cancel-owner")
		resultCh <- result{stats: stats, err: err}
	}()
	select {
	case <-provider.started:
	case <-ctx.Done():
		t.Fatalf("abstract provider did not start: %v", ctx.Err())
